/** Fontes embutidas do módulo Diploma UNIP (subconjunto Latin).
 *  UnipGothic = UnifrakturMaguntia (OFL) — substituto da Lohengrin da frente.
 *  UnipSerif  = Caladea (OFL) — métricas compatíveis com a Cambria do verso.
 */

export const UNIP_GOTHIC_B64 = "";

export const UNIP_SERIF_B64 = "";

export const UNIP_SERIF_ITALIC_B64 = "";

export const UNIP_SERIF_BOLD_B64 = "";

export const UNIP_FONT_FACES = `
@font-face { font-family: 'UnipGothic'; src: url(data:font/truetype;charset=utf-8;base64,${UNIP_GOTHIC_B64}) format('truetype'); font-weight: normal; font-style: normal; font-display: block; }
@font-face { font-family: 'UnipSerif'; src: url(data:font/truetype;charset=utf-8;base64,${UNIP_SERIF_B64}) format('truetype'); font-weight: normal; font-style: normal; font-display: block; }
@font-face { font-family: 'UnipSerif'; src: url(data:font/truetype;charset=utf-8;base64,${UNIP_SERIF_ITALIC_B64}) format('truetype'); font-weight: normal; font-style: italic; font-display: block; }
@font-face { font-family: 'UnipSerif'; src: url(data:font/truetype;charset=utf-8;base64,${UNIP_SERIF_BOLD_B64}) format('truetype'); font-weight: bold; font-style: normal; font-display: block; }
`;
